public boolean shouldPrintMessage(int timestamp, String message) {
    // Check if the timestamp is within the allowed range
    if (timestamp < 0 || timestamp > 1000000000) {
        throw new IllegalArgumentException("Timestamp must be between 0 and 1000000000");
    }

    // Check if the message is not null or empty
    if (message == null || message.isEmpty()) {
        throw new IllegalArgumentException("Message cannot be null or empty");
    }

    // Check if the message should be printed
    if (timestamp % 10 == 0) {
        return true;
    } else {
        return false;
    }
}

