    long result = 0;
    int shift = 0;
    while (true) {
        int b = read();
        if (b < 0) {
            throw new EOFException();
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
}

